-- IDENTIFICAMOS LOS IDS DE TARJETAS VIRTUALES OBSOLETAS, LAS CUALES TIENEN CREDITO ABIERTO Y TIENEN RESERVAS a FUTURO
SELECT     
	CTV.Ctv_Atributos								AS [Ctv_Atributos],
	CAST(DECOMPRESS(CTV.Ctv_Atributos) AS XML)		AS [XML_Atributos],
	TV.id_ctv										AS [id_ctv]

	--REPLACE(
	--		CAST(DECOMPRESS(CTV.Ctv_Atributos) AS VARCHAR(MAX)),
	--		'"NombreCertificado":"EFPLNJ84CHZPLUM2-W2M-638884244161564927"', -- ANTIGUO
	--		'"NombreCertificado":"EFPLNJ84CHZPLUM2-W2M-639166754471277453"'  -- NUEVO
	--		)
FROM			Tbl_TarjetaVirtual				TV
	LEFT JOIN	Tbl_ConfiguracionTarjetaVirtual CTV ON Tv.id_Ctv  = Ctv.id_Ctv
	LEFT JOIN	tbl_lineareserva                LR  ON TV.id_lre  = lr.id_lre
	LEFT JOIN	tbl_reserva						R   ON Lr.id_res  = R.id_res								
WHERE 
	1=1
	AND ctv.Ctv_Provider = 'BavelEPay'
	AND ctv.Ctv_Obsoleta = 1
	AND lr.LRe_finiViaje >= GETDATE()
	AND tv.tav_estado = 'Open'
	AND DECOMPRESS(CTV.Ctv_Atributos) LIKE '%638884244161564927%'
GROUP BY
	TV.id_ctv,
	CTV.Ctv_Atributos


